import { Component, OnDestroy, OnInit } from '@angular/core';

@Component({
  selector: 'app-class-timer',
  templateUrl: './class-timer.component.html',
  styleUrls: ['./class-timer.component.scss']
})
export class ClassTimerComponent implements OnInit, OnDestroy {

  totalSeconds = 300; // پیش‌فرض ۵ دقیقه
  remainingSeconds = 300;

  isRunning = false;
  isFinished = false;
  private intervalId: any = null;

  activityName = 'فعالیت کلاسی و کاربرگ';

  presets = [
    { label: '۱ دقیقه (پاسخ سریع)', sec: 60 },
    { label: '۳ دقیقه (روخوانی / املای کلمه)', sec: 180 },
    { label: '۵ دقیقه (کاربرگ ریاضی)', sec: 300 },
    { label: '۱۰ دقیقه (نقاشی و کار گروهی)', sec: 600 },
    { label: '۱۵ دقیقه (زنگ تفریح و استراحت)', sec: 900 },
    { label: '۲۰ دقیقه (ارزیابی جامع کلاسی)', sec: 1200 },
  ];

  ngOnInit(): void {
    this.remainingSeconds = this.totalSeconds;
  }

  ngOnDestroy(): void {
    this.stopTimer();
  }

  setPreset(sec: number, label: string): void {
    this.stopTimer();
    this.totalSeconds = sec;
    this.remainingSeconds = sec;
    this.activityName = label;
    this.isFinished = false;
  }

  startTimer(): void {
    if (this.isRunning) { return; }
    if (this.remainingSeconds <= 0) {
      this.remainingSeconds = this.totalSeconds;
    }

    this.isRunning = true;
    this.isFinished = false;

    this.intervalId = setInterval(() => {
      if (this.remainingSeconds > 0) {
        this.remainingSeconds--;
      } else {
        this.finishTimer();
      }
    }, 1000);
  }

  pauseTimer(): void {
    this.isRunning = false;
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  resetTimer(): void {
    this.pauseTimer();
    this.remainingSeconds = this.totalSeconds;
    this.isFinished = false;
  }

  private stopTimer(): void {
    this.isRunning = false;
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  private finishTimer(): void {
    this.stopTimer();
    this.isFinished = true;
    this.playChimeSound();
  }

  playChimeSound(): void {
    // بازخورد صوتی مرورگر با Web Audio API بدون نیاز به فایل صوتی
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(587.33, audioCtx.currentTime); // D5
      osc.frequency.exponentialRampToValueAtTime(880, audioCtx.currentTime + 0.3); // A5

      gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 1.2);

      osc.connect(gain);
      gain.connect(audioCtx.destination);

      osc.start();
      osc.stop(audioCtx.currentTime + 1.2);
    } catch (e) {
      // AudioContext fallback
    }
  }

  get progressPercentage(): number {
    if (this.totalSeconds <= 0) { return 0; }
    return ((this.totalSeconds - this.remainingSeconds) / this.totalSeconds) * 100;
  }

  get formattedTime(): string {
    const mins = Math.floor(this.remainingSeconds / 60);
    const secs = this.remainingSeconds % 60;
    const mStr = mins < 10 ? '۰' + mins : '' + mins;
    const sStr = secs < 10 ? '۰' + secs : '' + secs;
    return `${mStr}:${sStr}`;
  }
}
